#!/usr/bin/env bash
# This file was generated by Cursor AI on 2026-10-20.
# Sort-check all MoXI files in the repository with moxisc.

set -euo pipefail

if [[ -n "${MOXISC:-}" ]]; then
  moxisc="$MOXISC"
elif [[ $# -ge 1 ]]; then
  moxisc="$1"
else
  echo "usage: sortcheck.sh <path-to-moxisc>" >&2
  echo "   or: MOXISC=<path-to-moxisc> sortcheck.sh" >&2
  exit 2
fi

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root"

mapfile -t files < <(git ls-files -- '*.moxi')

if [[ ${#files[@]} -eq 0 ]]; then
  echo "error: no .moxi files found" >&2
  exit 1
fi

echo "Sort-checking ${#files[@]} MoXI files with $moxisc"

fails=0
for f in "${files[@]}"; do
  if ! output=$("$moxisc" "$f" 2>&1); then
    fails=$((fails + 1))
    echo "[FAIL] $f"
    if [[ -n "$output" ]]; then
      echo "$output"
    fi
  fi
done

echo "Checked ${#files[@]}, failed $fails"
if [[ "$fails" -ne 0 ]]; then
  exit 1
fi
